import { products, money } from './catalog.js';
const $=s=>document.querySelector(s),view=$('#view'),dialog=$('#cartDialog');
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let cart=read('nm-cart',[]); if(!Array.isArray(cart))cart=[];cart=cart.filter(id=>products.some(p=>p.id===id));cart=[...new Set(cart)];
let orders=read('nm-demo-orders',[]);if(!Array.isArray(orders))orders=[];orders=orders.filter(o=>o&&Array.isArray(o.items)&&typeof o.id==='string'&&Number.isFinite(o.date));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem('nm-cart',JSON.stringify(cart));localStorage.setItem('nm-demo-orders',JSON.stringify(orders))}catch{}$('#cartCount').textContent=cart.length};
const find=id=>products.find(p=>p.id===id);const selected=()=>cart.map(find).filter(Boolean);const total=()=>selected().reduce((n,p)=>n+p.price,0);
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function add(id){if(!find(id))return;if(cart.includes(id)){toast('Dieses Produkt liegt bereits im Warenkorb.');return}cart.push(id);save();toast('Zum Warenkorb hinzugefügt.');renderCart()}
const card=p=>`<article class="card"><a class="card-image" href="#product/${p.id}" aria-label="${p.name} ansehen"><img src="${p.image}" alt="${p.name} – Produktvorschau" loading="lazy"></a><div class="card-body"><h3><a href="#product/${p.id}">${p.name}</a></h3><p>${p.contents}</p><div class="card-bottom"><span class="price">${money(p.price)}</span><button class="icon-button" data-add="${p.id}" aria-label="${p.name} in den Warenkorb">＋</button></div></div></article>`;
const collection=(full=false)=>`<section class="panel collections"><div class="section-title"><div><h2>${full?'Alle Kollektionen':'Entdecke die Kollektionen'}</h2><p>Ausgewählte Designs für deinen digitalen Alltag.</p></div>${full?'<input class="search" id="search" type="search" aria-label="Produkte suchen" placeholder="Kollektion suchen …">':'<a href="#collections">Alle Produkte anzeigen →</a>'}</div>${full?'<div class="filters"><button class="chip active" data-filter="Alle">Alle</button><button class="chip" data-filter="Wallpaper">Wallpaper</button><button class="chip" data-filter="Streaming">Streaming</button></div>':''}<div class="grid" id="productGrid">${products.map(card).join('')}</div><p class="muted">Beispielprodukte und Beispielpreise · Die fertigen Pakete sind noch in Vorbereitung.</p><div class="benefits"><div>↓ &nbsp; Dein Downloadbereich<br><span>Alle Testkäufe an einem Ort</span></div><div>∞ &nbsp; Für deine Kreativität<br><span>Wallpaper, Panels und mehr</span></div><div>♡ &nbsp; Mit Liebe zum Detail<br><span>Der Look von NeonMind</span></div></div></section>`;
function home(){view.innerHTML=`<section class="hero"><div class="hero-copy"><span class="kicker">Digitale Designs · NeonMind</span><h1>Dein Bildschirm.<br><em>Deine Welt.</em></h1><p>Digitale Designs von NeonMind.</p><a class="button primary" href="#collections">Kollektion entdecken <span>→</span></a><div class="facts"><span><b>▧</b> Eigene<br>Designwelten</span><span><b>◇</b> Sorgfältige<br>Gestaltung</span><span><b>▯</b> Für PC &<br>Smartphone</span></div></div></section>${collection()}`}
function product(id){const p=find(id);if(!p){view.innerHTML='<div class="panel page empty"><h1>Produkt nicht gefunden</h1><a class="button" href="#collections">Zur Übersicht</a></div>';return}view.innerHTML=`<section class="page"><div class="breadcrumb"><a href="#home">Entdecken</a> › <a href="#collections">${p.category}</a> › ${p.name}</div><div class="panel product-layout"><div><img class="product-image" src="${p.image}" alt="${p.name} große Vorschau"><p class="muted">Motivvorschau · Noch kein vollständiges Produktpaket</p></div><div class="product-copy"><span class="kicker">${p.category} / NeonMind</span><h1>${p.name}</h1><p>${p.description}</p><span class="price">${money(p.price)}</span><span class="muted"> · Beispielpreis</span><ul class="detail-list"><li>${p.contents}</li><li>${p.formats}</li><li>Nutzungsrechte: werden vor Verkaufsstart festgelegt</li></ul><button class="button primary" data-add="${p.id}">＋ In den Warenkorb</button><p class="notice">Diese Vorschau nimmt keine Zahlungen an. Im Testkauf erhältst du ein einzelnes öffentliches Demobild.</p></div></div></section>`}
function renderCart(){const items=selected();$('#cartContent').innerHTML=items.length?`${items.map(p=>`<div class="cart-row"><img src="${p.image}" alt=""><div class="row-copy"><h3>${p.name}</h3><button class="remove" data-remove="${p.id}">Entfernen</button></div><span class="price">${money(p.price)}</span></div>`).join('')}<div class="summary-line total"><span>Gesamt</span><span>${money(total())}</span></div><p class="muted">Beispielpreise · Keine tatsächliche Zahlung</p><div class="cart-actions"><a class="button primary" href="#checkout" id="checkoutLink">Zur Testkasse →</a><button class="button" id="continueShopping">Weiter entdecken</button></div>`:'<div class="empty"><h2>Hier ist noch Platz.</h2><p class="muted">Entdecke deine nächste Designwelt.</p><button class="button primary" id="continueShopping">Kollektionen ansehen</button></div>'}
function previewCheckout(){if(!cart.length){view.innerHTML='<div class="panel page empty"><h2>Dein Warenkorb ist leer.</h2><a class="button primary" href="#collections">Kollektionen entdecken</a></div>';return}view.innerHTML=`<section class="page"><div class="breadcrumb"><a href="#collections">Kollektionen</a> › Testkasse</div><h1 style="font-size:40px">Deine Auswahl.</h1><p class="muted">Ein Testdurchlauf ohne Zahlung und ohne persönliche Daten.</p><div class="checkout-grid"><form class="panel" id="checkoutForm"><h2>Testkauf</h2><p>Der echte Zahlungsanschluss wird nach Einrichtung deines Betreiberkontos ergänzt.</p><label class="field">Testablauf<select id="testResult"><option value="success">Erfolgreicher Testkauf</option><option value="pending">Zahlung ausstehend simulieren</option><option value="failed">Fehlgeschlagene Zahlung simulieren</option></select></label><label class="check"><input type="checkbox" required>Ich verstehe, dass dies eine Vorschau mit Beispielprodukten ist und kein echter Kauf stattfindet.</label><button class="button primary" type="submit">Testkauf durchführen</button><p class="notice">Die Testhistorie wird nur in diesem Browser gespeichert. Sie bestätigt keine echte Zahlung und schaltet keine privaten Produkte frei.</p></form><aside class="panel"><h2>Bestellübersicht</h2>${selected().map(p=>`<div class="summary-line"><span>${p.name}</span><strong>${money(p.price)}</strong></div>`).join('')}<div class="summary-line total"><span>Beispielgesamtpreis</span><span>${money(total())}</span></div><p class="muted">Heute zahlst du: 0,00 €</p></aside></div></section>`;$('#checkoutForm').addEventListener('submit',e=>{e.preventDefault();const status=$('#testResult').value;if(status!=='success'){view.innerHTML=`<div class="panel page success"><h2>${status==='pending'?'Testzahlung ausstehend':'Testzahlung fehlgeschlagen'}</h2><p>Es wurden keine Downloads freigegeben.</p><button class="button primary" id="retryCheckout">Zurück zur Testkasse</button></div>`;return}const order={id:crypto.randomUUID(),date:Date.now(),items:[...cart],mode:'demo'};orders.unshift(order);cart=[];save();location.hash='#success/'+order.id})}
function previewDownloads(){const bought=[...new Set(orders.flatMap(o=>o.items))].map(find).filter(Boolean);view.innerHTML=`<section class="page"><div class="panel"><span class="kicker">Deine Designbibliothek</span><h1 style="font-size:42px">Meine Downloads</h1><p class="muted">Hier findest du die Demodateien deiner Testkäufe.</p>${bought.length?bought.map(p=>`<article class="download-row"><img src="${p.image}" alt=""><div class="row-copy"><h3>${p.name}</h3><p>Ein Demobild · Öffentliches Vorschauasset</p><span class="status">✓ Testkauf abgeschlossen</span></div><a class="button" href="${p.demo}" download="NeonMind-${p.id}-Demo.png">↓ Demobild herunterladen</a></article>`).join(''):'<div class="empty"><h2>Deine Sammlung beginnt hier.</h2><p class="muted">Nach einem Testkauf erscheint dein Demobild in diesem Bereich.</p><a class="button primary" href="#collections">Designs entdecken</a></div>'}<p class="notice">Im fertigen Shop werden private Downloads serverseitig freigegeben. Diese Vorschau verwendet ausschließlich öffentliche Demobilder.</p>${orders.length?'<button class="button" id="resetDemo">Testhistorie löschen</button>':''}</div></section>`}
function previewRoute(){dialog.close();const [page,id]=(location.hash.slice(1)||'home').split('/');if(page==='product')product(id);else if(page==='collections'){view.innerHTML='<div class="page">'+collection(true)+'</div>';let filter='Alle';const update=()=>{const q=$('#search').value.toLowerCase();const result=products.filter(p=>(filter==='Alle'||p.category===filter)&&p.name.toLowerCase().includes(q));$('#productGrid').innerHTML=result.length?result.map(card).join(''):'<p class="muted">Keine passende Kollektion gefunden.</p>'};$('#search').addEventListener('input',update);document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));update()}))}else if(page==='checkout')checkout();else if(page==='downloads')downloads();else if(page==='success'){const order=orders.find(o=>o.id===id);view.innerHTML=order?'<section class="page panel success"><span class="success-symbol">✓</span><h1 style="font-size:40px">Deine Designs warten.</h1><p>Der Testkauf ist abgeschlossen. Es wurde kein Geld abgebucht.</p><a class="button primary" href="#downloads">Zu meinen Downloads →</a></section>':'<div class="panel page empty"><h2>Testbestellung nicht gefunden.</h2><a href="#downloads">Zu den Downloads</a></div>'}else if(page==='info')view.innerHTML='<section class="page"><div class="panel content"><h1 style="font-size:40px">Über diese Vorschau</h1><p>NeonMind Shop ist ein eigenständiges Projekt von NeonMind. Diese private Vorschau zeigt das bestätigte Design und den geplanten Kaufablauf.</p><h2>Kein aktiver Verkauf</h2><p>Alle Preise und Produktpakete sind Beispiele. Es werden keine Zahlungen angenommen und keine persönlichen Kundendaten abgefragt. Der Warenkorb und ältere lokale Testkäufe liegen in deinem Browser. Neue Konto- und Gastbestellungen werden in der Shop-Datenbank gespeichert. Bei Registrierung werden E-Mail-Adresse und geschützter Passworthash gespeichert.</p><h2>Vor dem Verkaufsstart</h2><p>Betreiberangaben, Kontaktadresse, Impressum, Datenschutz, Verkaufsbedingungen und Nutzungsrechte werden mit den tatsächlichen Angaben ergänzt. Der Zahlungsanbieter und der private Dateispeicher sind noch einzurichten.</p><a class="button" href="#home">Zurück zum Shop</a></div></section>';else home();document.title=(page==='product'&&find(id)?find(id).name+' · ':'')+'NeonMind Shop';window.scrollTo(0,0)}
document.addEventListener('click',e=>{const addButton=e.target.closest('[data-add]');if(addButton)add(addButton.dataset.add);const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(id=>id!==remove.dataset.remove);save();renderCart()}if(e.target.closest('#continueShopping')){dialog.close();location.hash='#collections'}if(e.target.closest('#checkoutLink'))dialog.close();if(e.target.closest('#retryCheckout'))checkout();if(e.target.closest('#resetDemo')){orders=[];save();downloads();toast('Testhistorie gelöscht.')}});
$('#cartButton').addEventListener('click',()=>{renderCart();dialog.showModal()});$('#closeCart').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});window.addEventListener('hashchange',route);save();
let accountUser=null,accountCapabilities=null,guestReceipt=null,purchaseMode='guest';
async function api(path,body){const response=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json()}catch{throw new Error('Kundenkonten sind auf diesem Vorschau-Host noch nicht eingerichtet.')}if(!response.ok)throw new Error(data.error||'Bitte später erneut versuchen.');return data}
async function accountState(){try{accountCapabilities=await api('/api/health');if(accountCapabilities.accountsEnabled)accountUser=(await api('/api/me')).user;else accountUser=null}catch{accountCapabilities={accountsEnabled:false,guestOrdersEnabled:false};accountUser=null}return accountCapabilities}
function formError(error){const el=$('#accountError')||$('#checkoutError');if(el){el.textContent=error.message;el.hidden=false}else toast(error.message)}
function accountNotice(){return '<p class="notice">Kundenkonten werden gerade eingerichtet. Sobald die Shop-Datenbank angeschlossen ist, kannst du dich hier registrieren und deine Käufe dauerhaft abrufen.</p>'}
async function accountPage(kind='account'){await accountState();if((location.hash.slice(1)||'home')!==kind)return;const enabled=accountCapabilities.accountsEnabled;view.innerHTML=`<section class="page"><div class="panel content"><span class="kicker">Dein NeonMind-Bereich</span><h1 style="font-size:40px">${accountUser?'Dein Konto':kind==='register'?'Konto anlegen':'Anmelden'}</h1>${accountUser?`<p>Angemeldet als <strong>${esc(accountUser.email)}</strong></p><a class="button primary" href="#downloads">Meine Käufe & Downloads →</a><p><a href="#guest">Früheren Gastkauf übernehmen</a></p><button class="button" id="logoutAccount">Abmelden</button>`:!enabled?accountNotice():`<p class="muted">Mit einem Konto findest du deine Käufe auch auf anderen Geräten wieder.</p><form id="accountForm"><label class="field" for="accountEmail">E-Mail-Adresse<input id="accountEmail" type="email" maxlength="254" autocomplete="email" required></label><label class="field" for="accountPassword">Passwort<input id="accountPassword" type="password" minlength="12" maxlength="128" autocomplete="${kind==='register'?'new-password':'current-password'}" required></label><p class="muted">Mindestens 12 Zeichen. Konto und Bestellungen befinden sich noch im Testbetrieb.</p>${kind==='register'?'<label class="field" for="repeatPassword">Passwort wiederholen<input id="repeatPassword" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label>':''}<p class="notice">Noch kein aktiver Verkauf. E-Mail-Bestätigung und Passwort-Zurücksetzen folgen vor dem Verkaufsstart.</p><p id="accountError" class="notice" role="alert" hidden></p><button class="button primary" type="submit">${kind==='register'?'Konto anlegen':'Anmelden'}</button></form><p>${kind==='register'?'<a href="#login">Schon ein Konto? Anmelden →</a>':'<a href="#register">Noch kein Konto? Konto anlegen →</a>'}</p>`}<p><a href="#guest">Als Gast frühere Bestellung öffnen →</a></p></div></section>`;
 if($('#accountForm'))$('#accountForm').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const password=$('#accountPassword').value;if(kind==='register'&&password!==$('#repeatPassword').value)throw new Error('Die Passwörter stimmen nicht überein.');const result=await api(kind==='register'?'/api/register':'/api/login',{email:$('#accountEmail').value,password});accountUser=result.user;purchaseMode='account';toast(kind==='register'?'Konto angelegt.':'Du bist angemeldet.');location.hash=cart.length?'#checkout':'#downloads'}catch(error){formError(error)}finally{button.disabled=false}});
 if($('#logoutAccount'))$('#logoutAccount').addEventListener('click',async()=>{try{await api('/api/logout',{});accountUser=null;purchaseMode='guest';toast('Du bist abgemeldet.');location.hash='#account';await accountPage('account')}catch(error){formError(error)}});
}
async function checkout(){await accountState();if(location.hash!=='#checkout')return;if(!cart.length){previewCheckout();return}view.innerHTML=`<section class="page"><div class="breadcrumb"><a href="#collections">Kollektionen</a> › Testkasse</div><h1 style="font-size:40px">Wie möchtest du kaufen?</h1><p class="muted">Wähle Gastkauf oder dein Kundenkonto. Aktuell ohne echte Zahlung.</p><div class="checkout-grid"><form class="panel" id="customerCheckout"><div class="purchase-options"><label class="purchase-option"><input type="radio" name="purchaseMode" value="guest" ${purchaseMode==='guest'||!accountUser?'checked':''}><strong>Als Gast kaufen</strong><span>Ohne Konto. Zugang über deinen Bestellschlüssel.</span></label><label class="purchase-option"><input type="radio" name="purchaseMode" value="account" ${purchaseMode==='account'&&accountUser?'checked':''}><strong>Mit Kundenkonto</strong><span>Käufe nach der Anmeldung auf jedem Gerät wiederfinden.</span></label></div><div id="accountChoice"></div><label class="field" for="testResult">Testablauf<select id="testResult"><option value="success">Erfolgreicher Testkauf</option><option value="pending">Zahlung ausstehend simulieren</option><option value="failed">Fehlgeschlagene Zahlung simulieren</option></select></label><label class="check"><input type="checkbox" required>Ich verstehe, dass dies ein Testkauf ohne Zahlung mit Beispielprodukten ist.</label><p class="notice">${accountCapabilities.guestOrdersEnabled?'Testbestellungen werden auf dem Shop-Server gespeichert.':'Auf diesem Host ist die Datenbank noch nicht angeschlossen. Gast-Testkäufe bleiben vorübergehend in diesem Browser.'}</p><p id="checkoutError" class="notice" role="alert" hidden></p><button class="button primary" type="submit">Testkauf durchführen</button></form><aside class="panel"><h2>Deine Auswahl</h2>${selected().map(p=>`<div class="summary-line"><span>${p.name}</span><strong>${money(p.price)}</strong></div>`).join('')}<div class="summary-line total"><span>Beispielgesamtpreis</span><span>${money(total())}</span></div><p class="muted">Heute zahlst du: 0,00 €</p></aside></div></section>`;
 const choice=()=>{purchaseMode=$('input[name="purchaseMode"]:checked').value;$('#accountChoice').innerHTML=purchaseMode==='account'?(accountUser?`<p>Angemeldet als <strong>${esc(accountUser.email)}</strong></p>`:`<p><a class="button" href="#login">Anmelden</a> <a class="button" href="#register">Konto anlegen</a></p>${!accountCapabilities.accountsEnabled?accountNotice():''}`):'<p class="muted">Nach dem Testkauf erhältst du einen Bestellschlüssel. Bewahre ihn auf, damit du später wieder zugreifen kannst.</p>'};document.querySelectorAll('input[name="purchaseMode"]').forEach(el=>el.addEventListener('change',choice));choice();
 $('#customerCheckout').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button[type="submit"]');button.disabled=true;try{const result=$('#testResult').value;if(purchaseMode==='account'&&!accountUser)throw new Error('Bitte zuerst anmelden oder ein Konto anlegen.');if(accountCapabilities.guestOrdersEnabled){const receipt=await api('/api/orders/demo',{items:cart,purchaseMode,result});cart=[];save();if(receipt.guestKey){guestReceipt=receipt;location.hash='#guest'}else location.hash='#downloads'}else{if(result!=='success')throw new Error(result==='pending'?'Testzahlung ausstehend. Kein Download freigegeben.':'Testzahlung fehlgeschlagen. Kein Download freigegeben.');orders.unshift({id:crypto.randomUUID(),date:Date.now(),items:[...cart],mode:'demo'});cart=[];save();location.hash='#downloads'}}catch(error){formError(error)}finally{button.disabled=false}});
}
function orderCard(order){return `<section class="order-card"><div class="summary-line"><strong>Testbestellung ${esc(order.id.slice(0,8))}</strong><span class="status">Testkauf · Keine Zahlung</span></div><p class="muted">${new Date(order.created_at).toLocaleDateString('de-DE')} · Beispielwert ${money(order.amount)}</p>${order.items.map(item=>find(item.product_id)).filter(Boolean).map(p=>`<div class="download-row"><img src="${p.image}" alt=""><div class="row-copy"><h3>${p.name}</h3><p>Ein öffentliches Demobild</p></div><a class="button" href="${p.demo}" download="NeonMind-${p.id}-Demo.png">↓ Demobild herunterladen</a></div>`).join('')}</section>`}
async function downloads(){await accountState();if(location.hash!=='#downloads')return;if(accountUser){try{const result=await api('/api/orders');view.innerHTML=`<section class="page"><div class="panel"><span class="kicker">Deine Designbibliothek</span><h1 style="font-size:40px">Meine Käufe & Downloads</h1><p class="muted">${esc(accountUser.email)} · Deine serverseitig gespeicherten Testbestellungen</p>${result.orders.length?result.orders.map(orderCard).join(''):'<div class="empty"><h2>Deine Sammlung beginnt hier.</h2><a class="button primary" href="#collections">Designs entdecken</a></div>'}<p><a class="button" href="#guest">Gastbestellung übernehmen</a> <a class="button" href="#account">Mein Konto</a></p></div></section>`}catch(error){toast(error.message)}}else{previewDownloads();view.querySelector('.panel').insertAdjacentHTML('afterbegin','<div class="account-access"><a class="button" href="#login">Mit Konto anmelden</a><a class="button" href="#guest">Gastbestellung öffnen</a></div>')}}
async function guestPage(){await accountState();if(location.hash!=='#guest')return;view.innerHTML=`<section class="page"><div class="panel content"><span class="kicker">Ohne Kundenkonto</span><h1 style="font-size:40px">Dein Gastzugang</h1>${guestReceipt?`<p>Dein Testkauf ist abgeschlossen. Bewahre diesen Schlüssel auf: Er ermöglicht den späteren Zugang zu dieser Bestellung.</p><label class="field" for="receiptKey">Dein Bestellschlüssel<input id="receiptKey" value="${guestReceipt.guestKey}" readonly></label><button class="button primary" id="saveReceipt">Bestellzugang als Datei speichern</button><div id="guestOrder">${orderCard(guestReceipt.order)}</div>`:''}<form id="guestLookup"><label class="field" for="guestKey">Bestellschlüssel eingeben<input id="guestKey" autocomplete="off" minlength="64" maxlength="64" required ${guestReceipt?'value="'+guestReceipt.guestKey+'"':''}></label><p id="accountError" class="notice" role="alert" hidden></p><button class="button" type="submit">Bestellung öffnen</button></form>${!accountCapabilities.guestOrdersEnabled?accountNotice():''}<div id="lookupResult"></div><p class="notice">Der Schlüssel ist vertraulich. Wer ihn besitzt, kann diese Gastbestellung öffnen. Ohne gespeicherten Schlüssel ist die Wiederherstellung derzeit nicht möglich. E-Mail-Versand folgt vor Verkaufsstart.</p><p>${accountUser?'<button class="button" id="claimGuest">Diese Bestellung meinem Konto zuordnen</button>':'<a href="#register">Konto anlegen</a> oder <a href="#login">anmelden</a>, um einen Gastkauf ins Konto zu übernehmen.'}</p></div></section>`;
 $('#guestLookup').addEventListener('submit',async e=>{e.preventDefault();try{const result=await api('/api/guest/order',{key:$('#guestKey').value.trim()});$('#lookupResult').innerHTML=orderCard(result.order)}catch(error){formError(error)}});
 if($('#claimGuest'))$('#claimGuest').addEventListener('click',async()=>{try{await api('/api/guest/claim',{key:$('#guestKey').value.trim()});guestReceipt=null;toast('Bestellung deinem Konto zugeordnet.');location.hash='#downloads'}catch(error){formError(error)}});
 if($('#saveReceipt'))$('#saveReceipt').addEventListener('click',()=>{const blob=new Blob([`NeonMind Shop – Gastzugang (Testbestellung)\n\nShop: ${location.origin}\nBestellung: ${guestReceipt.order.id}\nBestellschlüssel: ${guestReceipt.guestKey}\n\nÖffne im Shop den Gastzugang und gib den Schlüssel ein. Vertraulich aufbewahren.\n`],{type:'text/plain;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='NeonMind-Bestellzugang.txt';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)});
}
function route(){const page=(location.hash.slice(1)||'home').split('/')[0];dialog.close();if(['account','login','register'].includes(page))accountPage(page);else if(page==='guest')guestPage();else if(page==='checkout')checkout();else if(page==='downloads')downloads();else previewRoute();window.scrollTo(0,0)}
route();
